(()=>{const A='#ff86c2',reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`body{background:radial-gradient(ellipse at 50% 0,#25284d 0,#0d1023 45%,#05060d 100%)}body:before{content:'';position:fixed;inset:0;pointer-events:none;z-index:-2;background:radial-gradient(circle at 18% 28%,#7e8bd518,transparent 28%),radial-gradient(circle at 82% 70%,#ff86c20c,transparent 32%)}.fxbar{position:fixed;top:0;left:0;width:100%;height:2px;background:#fff1;z-index:100}.fxbar i{display:block;height:100%;width:0;background:${A};box-shadow:0 0 15px ${A}}.fx-orb{position:fixed;border-radius:50%;pointer-events:none;filter:blur(100px);opacity:.13;z-index:-1}.fx-orb.a{width:450px;height:450px;left:-180px;top:5%;background:#5365a2;animation:drift 18s ease-in-out infinite}.fx-orb.b{width:400px;height:400px;right:-170px;bottom:5%;background:#d95b9d;animation:drift 22s ease-in-out infinite reverse}.fx-ink{position:fixed;pointer-events:none;z-index:2;width:18px;height:3px;border-radius:50%;background:#302438;box-shadow:0 0 8px #ff86c233;opacity:0;animation:ink 8s ease-in-out infinite;transform:rotate(-25deg)}.fx-heart{position:fixed;pointer-events:none;z-index:2;color:${A};opacity:0;filter:drop-shadow(0 0 8px #ff86c244);animation:heart 10s ease-out infinite}.fxr{opacity:0;transform:translateY(38px) scale(.985);transition:1s cubic-bezier(.2,.8,.2,1)}.fxr.on{opacity:1;transform:none}.writing:after{content:'|';animation:cursor .8s steps(1) infinite;color:${A}}.photo-slot.focused{transform:scale(1.025) rotate(-1deg);box-shadow:0 30px 90px #ff4f9d22}.answer-pop{animation:answer .7s ease}@keyframes drift{50%{transform:translate(85px,-50px)}}@keyframes ink{0%,100%{transform:translate(0,30px) rotate(-25deg) scale(.4);opacity:0}25%{opacity:.4}55%{transform:translate(35px,-75px) rotate(25deg) scale(1.1);opacity:.16}}@keyframes heart{0%{transform:translateY(18vh) rotate(-10deg) scale(.7);opacity:0}18%{opacity:.5}100%{transform:translateY(-105vh) translateX(45px) rotate(35deg) scale(1);opacity:0}}@keyframes cursor{50%{opacity:0}}@keyframes answer{50%{transform:scale(1.06)}}@media(prefers-reduced-motion:reduce){.fx-ink,.fx-heart{display:none}}`;b.appendChild(s);const bar=document.createElement('div');bar.className='fxbar';bar.innerHTML='<i></i>';b.appendChild(bar);['a','b'].forEach(c=>{const o=document.createElement('div');o.className='fx-orb '+c;b.appendChild(o)});if(!reduce){for(let i=0;i<30;i++){const p=document.createElement('i');p.className='fx-ink';p.style.left=Math.random()*100+'%';p.style.top=15+Math.random()*80+'%';p.style.animationDelay=-Math.random()*8+'s';p.style.animationDuration=6+Math.random()*6+'s';b.appendChild(p)}for(let i=0;i<16;i++){const h=document.createElement('span');h.className='fx-heart';h.textContent=['♡','♥','✦'][i%3];h.style.left=Math.random()*100+'%';h.style.fontSize=12+Math.random()*17+'px';h.style.animationDelay=-Math.random()*10+'s';b.appendChild(h)}}document.querySelectorAll('section').forEach(e=>e.classList.add('fxr'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fxr').forEach(e=>io.observe(e));addEventListener('scroll',()=>{const m=document.documentElement.scrollHeight-innerHeight;bar.firstElementChild.style.width=(m?scrollY/m*100:0)+'%'})})();